if(!г.шапка) отказ('Для свода нужна шапка: первая строка с названиями столбцов.');
const н = пмСтолбцы(т, г.имена).map(x => x.абс !== undefined ? x.абс : г.табл.c1 + x.отн).filter(c => c >= г.табл.c1 && c <= г.табл.c2);
