const s = пмЛат(т);
let ключ = null;
const послеПо = пмСтолбцы(т.replace(/^.*?(?:по каждому|по каждой|для каждого|для каждой|в разрезе|с разбивкой по|разбей по|разбивка по|(?<![а-я])по)\s+/i, ''), г.имена);
