if(ключ === null) ключ = н.find(c => !числа.includes(c)) ?? null;
if(ключ === null) for(let c = г.табл.c1; c <= г.табл.c2; c++) if(!числа.includes(c)){ ключ = c; break; }
if(ключ === null) отказ('По какому столбцу собрать свод? Например: «свод по менеджерам».');
let знач = н.filter(c => c !== ключ && числа.includes(c));
if(!знач.length) знач = числа.filter(c => c !== ключ);
const счёт = /сколько|количеств|число/.test(s) && !/сумм/.test(s);
if(!знач.length && !счёт) отказ('Нет числовых столбцов для сумм.');
