for(const r of г.данные.slice(1)){ const v = r[j]; if(пусто(v)) continue; if(!группы.some(x => x === v)) группы.push(v); }
const c0 = г.табл.c2 + 2, r0 = г.табл.r1, ширина = 1 + (счёт ? 1 : знач.length);
const место = await лс.прочитать(ОБЛ(r0, c0, r0 + группы.length + 1, c0 + ширина - 1));
if(место.some(r => r.some(v => !пусто(v)))) отказ('Справа от таблицы занято (' + ОБЛ(r0, c0, r0 + группы.length + 1, c0 + ширина - 1) + '): свод некуда поставить.');
const диап = c => '$' + БУКВА(c) + '$' + (г.r0 + 1) + ':$' + БУКВА(c) + '$' + (г.табл.r2 + 1);
лс.ячейка(АДР(r0, c0)).значение = г.имена[j];
(счёт ? [null] : знач).forEach((c, k) => { лс.ячейка(АДР(r0, c0 + 1 + k)).значение = c === null ? 'Количество' : г.имена[c - г.табл.c1]; });
группы.forEach((v, i) => {
const r = r0 + 1 + i;
лс.ячейка(АДР(r, c0)).значение = v;
(счёт ? [null] : знач).forEach((c, k) => { лс.ячейка(АДР(r, c0 + 1 + k)).формула = c === null ? 'СЧЁТЕСЛИ(' + диап(ключ) + ';' + АДР(r, c0) + ')' : 'СУММЕСЛИ(' + диап(ключ) + ';' + АДР(r, c0) + ';' + диап(c) + ')'; });
});
const ri = r0 + 1 + группы.length;
лс.ячейка(АДР(ri, c0)).значение = 'Итого';
for(let k = 1; k < ширина; k++) лс.ячейка(АДР(ri, c0 + k)).формула = 'СУММ(' + ОБЛ(r0 + 1, c0 + k, ri - 1, c0 + k) + ')';
const тонкая = {вид: 'тонкая', цвет: '#adb5bd'};
каждая(лс, {r1: r0, c1: c0, r2: ri, c2: c0 + ширина - 1}, (к, r, c) => {
const ст = {гр: {в: тонкая, н: тонкая, л: тонкая, п: тонкая}};
if(r === r0 || r === ri) ст.b = 1; if(r === r0) ст.fill = '#dbe4ff';
if(c > c0 && r > r0) ст.fmt = '#,##0.##';
к.стиль = ст;
});
